sys_ws_operation.operation_script:
(function process(request, response) {
    var runId = request.pathParams.run_id;
    var items = request.body.data.actions || [];
    var ids = [];
    for (var i = 0; i < items.length; i++) {
        var a = items[i];
        var gr = new GlideRecord('x_1821654_governa_action');
        gr.initialize();
        gr.setValue('run', runId);
        gr.setValue('sequence', a.sequence);
        gr.setValue('tool', a.tool);
        gr.setValue('target_table', a.target_table || '');
        gr.setValue('target_sys_id', a.target_sys_id || '');
        gr.setValue('params_hash', a.params_hash || '');
        gr.setValue('policy_decision', a.policy_decision || 'allow');
        gr.setValue('executed', a.executed === true);
        gr.setValue('occurred_at', a.occurred_at);
        ids.push(gr.insert());
    }
    response.setStatus(201);
    return { inserted: ids.length, sys_ids: ids };
})(request, response);
